pub fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // If bounds are reversed, output is max_val repeated.
    if min_val > max_val {
        return vec![max_val; arr.len()];
    }

    let mut out = Vec::with_capacity(arr.len());
    for &x in arr.iter() {
        let clipped = if x < min_val {
            min_val
        } else if x > max_val {
            max_val
        } else {
            x
        };
        out.push(clipped);
    }
    out
}

